\title{A Formal Development of the Deletion--Contraction Recurrence\\
and Structural Properties of the Chromatic Polynomial}
\author{Aristotle}
\date{2026-06-21}

\begin{document}
\maketitle

\begin{abstract}
The chromatic polynomial $P(G,k)$ of a finite simple graph $G$ counts the number
of proper $k$-colorings of $G$ and is the central enumerative invariant of graph
coloring. We present a self-contained development of two pillars of the theory.
First, we establish the \emph{deletion--contraction recurrence} in its
edge-addition form,
\[
P(G,k) = P(G+uv,\,k) + P(G/uv,\,k)
\]
for any pair of distinct, non-adjacent vertices $u,v$, where $G+uv$ adds the edge
$uv$ and $G/uv$ contracts (identifies) $u$ and $v$. Unlike the usual textbook
derivation, our proof is built on an \emph{explicit bijection} between the proper
colorings of $G$ and the disjoint union of the colorings of $G+uv$ (those with
$c(u)\neq c(v)$) and the colorings of $G/uv$ (those with $c(u)=c(v)$). The
bijection is given by mutually inverse \emph{extend} and \emph{restrict}
operations, and the recurrence follows by additivity of cardinality over a
disjoint union. Second, from the subset expansion of the chromatic polynomial
over edge sets we prove the two foundational structural facts: $P(G,k)$ has
\emph{degree} $|V|$ and is \emph{monic}. The key combinatorial lemma is that any
nonempty set of non-loop edges yields strictly fewer than $|V|$ connected
components, while the empty set yields exactly $|V|$. All results are fully
formalized and machine-checked.
\end{abstract}

\section{Introduction}
Graph coloring assigns labels (``colors'') to vertices so that adjacent vertices
receive distinct labels. The enumeration of proper labelings is governed by the
\emph{chromatic polynomial}, introduced by Birkhoff in 1912. For a finite simple
graph $G$ on vertex set $V$ and $k$ available colors, the number $P(G,k)$ of
proper $k$-colorings agrees with a monic integer polynomial of degree $|V|$ in
$k$. The computational backbone of the subject is the \emph{deletion--contraction
recurrence}, a divide-and-conquer identity reducing a graph's chromatic
polynomial to those of strictly simpler graphs.

This paper gives a rigorous, formally verified account of the recurrence and the
first structural properties it implies. Our emphasis is on constructive honesty:
the recurrence is derived from an explicit bijection rather than assumed.

\paragraph{Contributions.}
(1) A precise formalization of proper colorings, the chromatic counting function,
edge addition, and edge contraction. (2) An explicit bijection proof that the
colorings of a contraction $G/uv$ correspond to colorings of $G$ agreeing on $u$
and $v$ (Theorem~\ref{thm:contract}). (3) The deletion--contraction recurrence
(Theorem~\ref{thm:dc}). (4) The degree and monicity of the chromatic polynomial
(Theorems~\ref{thm:deg}, \ref{thm:monic}).

\section{Preliminaries}
Throughout, $V$ is a finite type with decidable equality and $G$ is a finite
simple graph on $V$: an irreflexive, symmetric adjacency relation $\Adj$. We
write $u\sim v$ for $\Adj(u,v)$. For $k\in\N$, a $k$-coloring is a function
$c:V\to\Fin k$. A coloring $c$ is \emph{proper} if $c(a)\neq c(b)$ whenever
$a\sim b$. We write $\Col(G,k)$ for the finite set of proper $k$-colorings.

\section{Core Definitions}

\begin{definition}[Proper colorings]
For a finite simple graph $G$ on a fintype $W$,
\[
\Col(G,k) = \{\, c:W\to\Fin k \mid \forall a,b,\; a\sim b \Rightarrow c(a)\neq c(b)\,\}.
\]
\end{definition}

\begin{definition}[Chromatic counting function]
$P(G,k) = |\Col(G,k)|$.
\end{definition}

\begin{definition}[Edge addition]
$G+uv$ has adjacency
\[
a\sim_{G+uv} b \iff (a\sim_G b)\;\lor\;\bigl(a\neq b\land((a=u\land b=v)\lor(a=v\land b=u))\bigr).
\]
\end{definition}

\begin{definition}[Edge contraction]
$G/uv$ has vertex type $\{x:V\mid x\neq v\}$ and adjacency
\[
a\sim_{G/uv} b \iff (a\sim_G b)\;\lor\;\bigl(a\neq b\land((a=u\land v\sim_G b)\lor(b=u\land a\sim_G v))\bigr).
\]
The second disjunct re-routes every edge of $G$ incident to $v$ to be incident to
the surviving vertex $u$.
\end{definition}

\section{Colorings of an Edge-Augmented Graph}

\begin{lemma}[\texttt{colorings\_addEdge}]\label{lem:add}
For distinct vertices $u\neq v$,
\[
\Col(G+uv,\,k) = \{\, c\in\Col(G,k)\mid c(u)\neq c(v)\,\}.
\]
\end{lemma}
\begin{proof}
$c$ is proper for $G+uv$ iff it respects every edge of $G$ and additionally
respects the new edge $uv$, i.e.\ $c(u)\neq c(v)$.
\end{proof}

Taking cardinalities,
\begin{equation}\label{eq:add}
P(G+uv,\,k) = \#\{c\in\Col(G,k)\mid c(u)\neq c(v)\}.
\end{equation}

\section{Colorings of a Contraction: The Explicit Bijection}

\begin{definition}[Extend and restrict]
For $u\neq v$: given $c':\{x\mid x\neq v\}\to\Fin k$, define $\ext(c'):V\to\Fin k$
by $\ext(c')(x) = c'(u)$ if $x=v$ and $\ext(c')(x)=c'(x)$ otherwise; in
particular $\ext(c')(u)=\ext(c')(v)$. Given $c:V\to\Fin k$, define
$\res(c)(x)=c(x)$ on $\{x\mid x\neq v\}$.
\end{definition}

\begin{lemma}[Inverse relations]\label{lem:inv}
$\res(\ext(c'))=c'$ for all $c'$; and $\ext(\res(c))=c$ whenever $c(u)=c(v)$.
\end{lemma}
\begin{proof}
For the first, on $x\neq v$ both operations leave $c'(x)$ unchanged. For the
second, on $x\neq v$ both sides equal $c(x)$; on $x=v$ the left is
$\res(c)(u)=c(u)=c(v)$.
\end{proof}

\begin{lemma}[Extension preserves properness]\label{lem:extmem}
Suppose $u\not\sim_G v$ and $u\neq v$. If $c'$ is proper for $G/uv$, then
$\ext(c')$ is proper for $G$ and $\ext(c')(u)=\ext(c')(v)$.
\end{lemma}
\begin{proof}
The color equality is immediate. For properness, take an edge $a\sim_G b$, so
$a\neq b$, and argue by cases on whether $a$ or $b$ equals $v$. If neither, the
values are $c'(a),c'(b)$ and $a\sim_{G/uv}b$ via the first disjunct. If $a=v$,
$b\neq v$, the values are $c'(u),c'(b)$ and $u\sim_{G/uv}b$ via the re-routing
disjunct (using $v\sim_G b$); the case $b=v$ is symmetric. The hypothesis
$u\not\sim_G v$ prevents a re-routed loop at the merged vertex.
\end{proof}

\begin{lemma}[Restriction preserves properness]\label{lem:resmem}
If $c$ is proper for $G$ with $c(u)=c(v)$, then $\res(c)$ is proper for $G/uv$.
\end{lemma}
\begin{proof}
Take $a\sim_{G/uv}b$. If from the first disjunct, $a\sim_G b$ gives $c(a)\neq
c(b)$. If from the re-routing disjunct, say $a=u$ with $v\sim_G b$, then
$c(v)\neq c(b)$ and $c(u)=c(v)$ give $c(a)\neq c(b)$.
\end{proof}

\begin{theorem}[Contraction count, \texttt{chromaticPolynomial\_contractEdge\_eq}]\label{thm:contract}
Suppose $u\not\sim_G v$ and $u\neq v$. Then
\[
P(G/uv,\,k) = \#\{c\in\Col(G,k)\mid c(u)=c(v)\}.
\]
\end{theorem}
\begin{proof}
Apply the bijection principle with forward map $c'\mapsto\ext(c')$ and inverse
$c\mapsto\res(c)$. Lemma~\ref{lem:extmem} shows the forward map lands in the
target; Lemma~\ref{lem:resmem} shows the inverse lands in $\Col(G/uv,k)$; and
Lemma~\ref{lem:inv} shows they are mutually inverse. Hence the sets are
equinumerous.
\end{proof}

\section{The Deletion--Contraction Recurrence}

\begin{theorem}[Deletion--contraction, edge-addition form]\label{thm:dc}
For distinct non-adjacent vertices $u\not\sim_G v$, $u\neq v$,
\[
P(G,k) = P(G+uv,\,k) + P(G/uv,\,k).
\]
\end{theorem}
\begin{proof}
Partition $\Col(G,k)$ by the predicate $c(u)=c(v)$ into disjoint blocks
$S_{\neq}$ and $S_{=}$ whose union is $\Col(G,k)$. By additivity of cardinality,
$P(G,k)=|S_{\neq}|+|S_{=}|$. By~\eqref{eq:add}, $|S_{\neq}|=P(G+uv,k)$; by
Theorem~\ref{thm:contract}, $|S_{=}|=P(G/uv,k)$.
\end{proof}

\begin{remark}
Writing $H=G+uv$ and $G=H-uv$ recovers the classical form
$P(H,k)=P(H-uv,k)-P(H/uv,k)$. The edge-addition form gives a clean termination
measure toward the complete graph $K_n$, whose base case is
$P(K_n,k)=k(k-1)\cdots(k-n+1)$.
\end{remark}

\paragraph{Worked example.}
For the path $a-b-c$ with $u=a$, $v=c$: $G+ac$ is the triangle with
$P=k(k-1)(k-2)$ and $G/ac$ is a single edge with $P=k(k-1)$, so
$P(\text{path},k)=k(k-1)(k-2)+k(k-1)=k(k-1)^2$.

\section{Structural Properties: Degree and Monicity}

We use the subset expansion
\begin{equation}\label{eq:expansion}
P(G,k) = \sum_{A\subseteq E(G)} (-1)^{|A|}\, k^{\,c(A)},
\end{equation}
where $E(G)$ is the edge set and $c(A)$ the number of connected components of the
spanning subgraph on the edges $A$.

\begin{lemma}[\texttt{numComponentsOfEdges\_empty}]\label{lem:empty}
$c(\varnothing)=|V|$.
\end{lemma}
\begin{proof}
With no edges, reachability is equality, so each vertex is its own component; the
component map is a bijection onto components.
\end{proof}

\begin{lemma}[\texttt{numComponentsOfEdges\_lt\_of\_nonempty}]\label{lem:lt}
If $A\neq\varnothing$ and every $e\in A$ is a non-loop edge, then $c(A)<|V|$.
\end{lemma}
\begin{proof}
Pick $s(u,v)\in A$ with $u\neq v$. Then $u,v$ are reachable, hence in the same
component, so the component map is not injective; a surjective non-injective map
on a finite set forces a strictly smaller image.
\end{proof}

\begin{theorem}[Degree, \texttt{natDegree\_chromaticPolynomial}]\label{thm:deg}
For $G$ on a nonempty vertex set, $\deg P(G,k)=|V|$.
\end{theorem}
\begin{proof}
In~\eqref{eq:expansion} the coefficient of $k^{|V|}$ is
$\sum_A (-1)^{|A|}[c(A)=|V|]$. By Lemmas~\ref{lem:empty} and~\ref{lem:lt} the only
contributing set is $A=\varnothing$, giving coefficient $1\neq 0$. Since
$c(A)\le|V|$ always, no higher power appears.
\end{proof}

\begin{theorem}[Monicity, \texttt{monic\_chromaticPolynomial}]\label{thm:monic}
For $G$ on a nonempty vertex set, $P(G,k)$ is monic; its leading coefficient
is $1$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:deg} the leading coefficient is the coefficient of $k^{|V|}$,
computed to be $1$.
\end{proof}

\section{Algorithms}
\textbf{Recursive evaluation.} If $G$ is complete, return
$k(k-1)\cdots(k-n+1)$; otherwise pick a non-adjacent pair $u\not\sim v$ and
return $P(G+uv,k)+P(G/uv,k)$. Termination follows since edge addition increases
the edge count toward $\binom{n}{2}$ and contraction decreases the vertex count.
\textbf{Direct enumeration.} Enumerate all $k^n$ colorings, filter the proper
ones, and count; used to cross-check small instances.

\section{Applications}
Examination/shift scheduling (events, conflicts, time slots); compiler register
allocation (live variables, interference, registers); frequency assignment; the
zero-temperature Potts model in statistical mechanics; and the Four Color
Theorem, equivalent to $P(G,4)>0$ for all planar $G$.

\section{Discussion}
The distinguishing feature is the constructive treatment of the recurrence: by
exhibiting an explicit extend/restrict bijection that preserves properness in
both directions, we obtain deletion--contraction as a corollary of a genuine
one-to-one correspondence, checkable end to end. The structural theorems follow
from the subset expansion via a single component-counting lemma.

\section{Future Directions}
(1) Package the counting function into a unique monic $\chi_G\in\Z[X]$ of degree
$|V|$ with sign-alternating coefficients. (2) Prove the absence of chromatic
roots in $(-\infty,0)\cup(0,1)\cup(1,32/27)$. (3) A formal Brooks' theorem:
$\chi(G)\le\Delta(G)$ outside complete graphs and odd cycles. (4) Reformulate the
Four Color Theorem as $P(G,4)>0$ for all planar $G$ via the positivity criterion.

\end{document}

