function ChromaticPolynomial(G = (V, E), k):
    n <- |V|
    if |E| == n*(n-1)/2:                # G is complete
        return product_{i=0}^{n-1} max(k - i, 0)
    choose (u, v) with u != v and {u,v} not in E
    G_plus     <- (V, E ∪ {{u,v}})       # add edge uv
    G_contract <- Contract(G, u, v)      # merge v into u, relabel
    return ChromaticPolynomial(G_plus, k)
         + ChromaticPolynomial(G_contract, k)

function Contract(G = (V, E), u, v):
    E' <- {}
    for {a, b} in E:
        a <- u if a == v else a
        b <- u if b == v else b
        if a != b: add {a, b} to E'     # drop loops, dedupe
    relabel V \ {v} to 0..n-2 and apply to E'
    return ((n-1), E')

